$st=db()->prepare("SELECT * FROM cars $where ORDER BY seats,day_price,name");$st->execute($params);$cars=$st->fetchAll();
$allSeats=db()->query('SELECT DISTINCT seats FROM cars WHERE active=1 ORDER BY seats')->fetchAll(PDO::FETCH_COLUMN);
$f=getFlash();
pageTop('Jainam Car Rental');nav('home');
?><main><section class="hero"><div><p class="eyebrow">JAINAM CAR RENTAL</p><h1>Book cars, tempo travellers & buses with confidence.</h1><p>Choose your vehicle, see its gallery/360 view, calculate live road KM and reserve it from your customer account.</p><div class="hero-actions"><a class="btn primary" href="#fleet">Explore Fleet</a><?php if(!isLoggedIn()): ?><a class="btn ghost" href="register.php">Create Customer Account</a><?php endif; ?></div></div><div class="hero-card"><b>Database-driven</b><span>Live availability • Customer history • Admin controls</span></div></section>
<?php if($f): ?><div class="container"><div class="flash <?=$f['type']?>"><?=e($f['message'])?></div></div><?php endif; ?>
<section id="fleet" class="container"><div class="section-head"><div><p class="eyebrow">FLEET</p><h2>Choose your budget</h2></div><div class="tabs"><a class="tab <?=$budget==='low'?'active':''?>" href="?budget=low">Low</a><a class="tab <?=$budget==='medium'?'active':''?>" href="?budget=medium">Medium</a><a class="tab <?=$budget==='high'?'active':''?>" href="?budget=high">High</a></div></div><div class="seat-tabs"><a class="seat <?=$seats===0?'active':''?>" href="?budget=<?=e($budget)?>">All</a><?php foreach($allSeats as $s): ?><a class="seat <?=$seats===(int)$s?'active':''?>" href="?budget=<?=e($budget)?>&seats=<?=$s?>"><?=$s?> seats</a><?php endforeach; ?></div>
<div class="car-grid"><?php foreach($cars as $car): $imgs=db()->prepare('SELECT image_url FROM car_images WHERE car_id=? ORDER BY angle_no');$imgs->execute([$car['id']]);$gallery=$imgs->fetchAll(PDO::FETCH_COLUMN);if(!$gallery&&$car['image_url'])$gallery=[$car['image_url']]; ?><article class="car-card"><div class="car-photo" onclick='open360(<?=json_encode((int)$car['id'])?>,<?=json_encode($car['name'])?>,<?=json_encode($gallery,JSON_UNESCAPED_SLASHES)?>)'><img src="<?=e($gallery[0]??'')?>" alt="<?=e($car['name'])?>" onerror="this.src='https://placehold.co/1200x750/1c1410/d4a373?text=<?=rawurlencode($car['name'])?>'"><span class="view360">↻ 360° / Gallery</span></div><div class="car-body"><div class="tag-row"><span class="tag"><?=e($car['seats'])?> seats</span><span class="tag"><?=e(ucfirst($car['budget']))?></span></div><h3><?=e($car['name'])?></h3><p class="muted"><?=e($car['type'])?></p><div class="specs"><span><?=e($car['fuel'])?></span><span><?=e($car['transmission'])?></span><span><?=e($car['ac'])?></span></div><div class="price-row"><div><b><?=money((float)$car['day_price'])?></b><small>/day</small><br><small>+ <?=money((float)$car['km_price'])?> / km</small></div><?php if(isLoggedIn() && user()['role']==='customer'): ?><a class="btn primary smallbtn" href="booking.php?car_id=<?=$car['id']?>">Book</a><?php else: ?><a class="btn ghost smallbtn" href="login.php">Login to Book</a><?php endif; ?></div></div></article><?php endforeach; ?></div><?php if(!$cars): ?><div class="empty">No vehicles found for this filter.</div><?php endif; ?></section></main>
<div id="viewer" class="modal"><div class="modal-box viewer-box"><button class="close" onclick="close360()">×</button><p class="eyebrow">360° VIEWER</p><h2 id="viewerTitle"></h2><div class="viewer-stage"><img id="viewerImg" alt="Vehicle view"><button class="viewer-btn left" onclick="viewerPrev()">‹</button><button class="viewer-btn right" onclick="viewerNext()">›</button></div><div class="viewer-controls"><input id="viewerRange" type="range" min="0" max="0" value="0" oninput="viewerGo(this.value)"><span id="viewerCount">1 / 1</span></div><p class="muted">For a true 360° rotation, upload multiple angle images for this vehicle from the Admin → Cars & Fleet panel.</p></div></div>
<script>let viewerImages=[],viewerIndex=0;function open360(id,name,imgs){viewerImages=imgs||[];viewerIndex=0;document.getElementById('viewerTitle').textContent=name;document.getElementById('viewerRange').max=Math.max(0,viewerImages.length-1);viewerRender();document.getElementById('viewer').classList.add('show')}function viewerRender(){let img=document.getElementById('viewerImg');img.src=viewerImages[viewerIndex]||'https://placehold.co/1200x750/1c1410/d4a373?text=Vehicle';document.getElementById('viewerRange').value=viewerIndex;document.getElementById('viewerCount').textContent=(viewerIndex+1)+' / '+Math.max(1,viewerImages.length)}function viewerGo(v){viewerIndex=+v;viewerRender()}function viewerPrev(){if(viewerImages.length){viewerIndex=(viewerIndex-1+viewerImages.length)%viewerImages.length;viewerRender()}}function viewerNext(){if(viewerImages.length){viewerIndex=(viewerIndex+1)%viewerImages.length;viewerRender()}}function close360(){document.getElementById('viewer').classList.remove('show')}document.getElementById('viewer').addEventListener('click',e=>{if(e.target.id==='viewer')close360()});</script><?php pageBottom(); ?>